    for(table,values)in [("dwg_entity_extrusion_coordinate",&d.extrusion),("dwg_dimension_text_midpoint_coordinate",&d.text_midpoint),("dwg_dimension_insertion_scale_coordinate",&d.insertion_scale),("dwg_dimension_clone_insertion_coordinate",&d.clone_insertion_point),("dwg_dimension_extension_line_1_coordinate",&v.extension_line_1),("dwg_dimension_extension_line_2_coordinate",&v.extension_line_2),("dwg_dimension_definition_coordinate",&v.definition_point)]{coordinates(projection,table,id,values)?;}
    Ok(())
